package fixture

import (
    "strconv"
    "strings"
)

func Parse(line string) (id int, text string, ok bool) {
    head, tail, found := strings.Cut(line, ":")
    if !found || head == "" || strings.Trim(head, "0123456789") != "" { return 0, "", false }
    id, err := strconv.Atoi(head)
    text = strings.TrimSpace(tail)
    if err != nil || id <= 0 || text == "" { return 0, "", false }
    return id, text, true
}

func IDs(lines []string) []int {
    out := []int{}
    for _, line := range lines {
        if id, _, ok := Parse(line); ok { out = append(out, id) }
    }
    return out
}

