package fixture_test

import (
    "reflect"
    "testing"
    f "fixture"
)

func TestChangingContract(t *testing.T) {
    input := []string{"  alpha "," ","雪","beta ",""}
    original := append([]string(nil), input...)
    records := f.Produce(input)
    expected := []f.Record{{ID:1,Text:"alpha"},{ID:3,Text:"雪"},{ID:4,Text:"beta"}}
    if !reflect.DeepEqual(records,expected) { t.Fatalf("records: %v",records) }
    if !reflect.DeepEqual(f.Consume(records),[]string{"1:alpha","3:雪","4:beta"}) { t.Fatal("consumer") }
    if !reflect.DeepEqual(records,expected) || !reflect.DeepEqual(input,original) { t.Fatal("mutation") }
    if len(f.Produce(nil))!=0 || len(f.Consume(nil))!=0 { t.Fatal("empty") }
    if !reflect.DeepEqual(f.Consume([]f.Record{{8,"x"},{2,"x"}}),[]string{"8:x","2:x"}) { t.Fatal("order/id preservation") }
}

func TestProducerFollowUps(t *testing.T) {
    input := []string{" a","b ","","b","c","a","b","  "}
    original := append([]string(nil), input...)
    kept,dropped := f.Stats(input)
    if kept != 6 || dropped != 2 { t.Fatal("stats") }
    kept,dropped = f.Stats([]string{"", "  "})
    if kept != 0 || dropped != 2 { t.Fatal("blank stats") }
    if !reflect.DeepEqual(f.Duplicates(input),[]string{"a","b"}) { t.Fatalf("duplicates: %v",f.Duplicates(input)) }
    if len(f.Duplicates(nil))!=0 || len(f.Duplicates([]string{"x"," y","z "}))!=0 { t.Fatal("no duplicates") }
    if !reflect.DeepEqual(input,original) { t.Fatal("mutation") }
}

func TestConsumerFollowUps(t *testing.T) {
    cases := []struct{ line string; id int; text string; ok bool }{
        {"1:alpha",1,"alpha",true}, {"42:  a:b ",42,"a:b",true}, {"007:雪",7,"雪",true},
        {"0:x",0,"",false}, {"-1:x",0,"",false}, {"+5:x",0,"",false}, {" 5:x",0,"",false},
        {"5 :x",0,"",false}, {"5:  ",0,"",false}, {"5",0,"",false}, {":x",0,"",false},
        {"x:y",0,"",false}, {"99999999999999999999:x",0,"",false},
    }
    for _, c := range cases {
        id,text,ok := f.Parse(c.line)
        if id != c.id || text != c.text || ok != c.ok { t.Fatalf("parse %q: %d %q %v",c.line,id,text,ok) }
    }
    input := []string{"3:c","bad","1:a","0:z","3:again"}
    original := append([]string(nil), input...)
    if !reflect.DeepEqual(f.IDs(input),[]int{3,1,3}) { t.Fatal("ids") }
    if !reflect.DeepEqual(input,original) { t.Fatal("mutation") }
    if len(f.IDs(nil))!=0 || len(f.IDs([]string{"x"}))!=0 { t.Fatal("empty ids") }
}
